import sys

def fun(S):
    MOD = 10**9 + 7
    count_a = 0
    count_ab = 0
    count_abc = 0

    for char in S:
        if char == 'a':
            count_a = (count_a * 2 + 1) % MOD
        elif char == 'b':
            count_ab = (count_ab * 2 + count_a) % MOD
        elif char == 'c':
            count_abc = (count_abc * 2 + count_ab) % MOD

    return count_abc

if __name__ == "__main__":
    s = sys.stdin.read().strip()
    result = fun(s)
    print(result)
